    fn mock_ui_prompt_falls_back_to_default() {
        let mut ui = MockUI::new();

        let prompt = Prompt {
            key: "env".to_string(),
            question: "Environment?".to_string(),
            prompt_type: PromptType::Input,
            default: Some("development".to_string()),
