+    #[test]
+    fn scrub_ignores_non_secret_env_vars() {
+        let mut env = HashMap::new();
+        env.insert("PATH".to_string(), "/usr/bin".to_string());
+        env.insert("HOME".to_string(), "/Users/dev".to_string());
+
+        let input = "using /usr/bin/gcc";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        // PATH is not a secret pattern, so its value shouldn't be masked by the OutputMasker.
+        // However /usr/bin might not match PATH_REGEX either (no /Users/, /home/, /tmp/, C:\Users\)
+        // so the value may remain.
+        assert!(!scrubbed.contains("secret"));
+    }
