+    #[test]
+    fn scrub_truncation_at_boundary() {
+        // Use "ab " to avoid matching hex/base64 token regexes.
+        // Pad to exactly MAX_ERROR_LENGTH.
+        let word = "ab ";
+        let count = (MAX_ERROR_LENGTH / word.len()) + 1;
+        let padded = word.repeat(count);
+        let input = &padded[..MAX_ERROR_LENGTH];
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
+        assert!(!scrubbed.ends_with("...[truncated]"));
+    }
+
+    #[test]
+    fn scrub_truncation_one_over_boundary() {
+        let word = "ok ";
+        let count = (MAX_ERROR_LENGTH + 10) / word.len();
+        let input = word.repeat(count);
+        assert!(input.len() > MAX_ERROR_LENGTH);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert!(scrubbed.ends_with("...[truncated]"));
+        assert!(scrubbed.len() <= MAX_ERROR_LENGTH + 14);
+    }
